contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bytes memory payload) public {
        require(payload.length != 4 || bytes4(payload) != bytes4(keccak256("nonExistentFunction()")));
        bool reverted;
        c.forward(address(this), payload); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted);
    }

    fallback() external payable {}

    receive() external payable {}
}

