pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(bytes memory payload) internal {
        vm.assume(payload.length != 4 || bytes4(payload) != bytes4(keccak256("nonExistentFunction()")));
        bool reverted;
        try c.forward(address(this), payload) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted);
    }

    function testFuzz_run(bytes memory payload) public {
        _run(payload);
    }

    fallback() external payable {}

    receive() external payable {}
}
